import test from 'node:test';
import assert from 'node:assert/strict';
import {activeContour,morphGAC,morphACWE} from '../src/browser-active-contours.js';

// Golden outputs were generated by scikit-image revision
// 533b7694d2004ae84e49e2cfd0bcfc5f8e562f22.
// This fixture is analytic, so the test does not depend on image files.
test('browser Active Contour stays within subpixel parity of scikit-image',()=>{
  const n=48,w=n,h=n,image=new Float32Array(n*n),snake=[];
  for(let y=0;y<n;y++)for(let x=0;x<n;x++){
    const r=Math.hypot(x-24,y-23);
    image[y*n+x]=.25+.65/(1+Math.exp(-(r-12)*1.5));
  }
  for(let i=0;i<32;i++){const s=i*2*Math.PI/32;snake.push([23+15*Math.sin(s),24+15*Math.cos(s)]);}
  const golden=[[23,37.0008],[25.6838,36.7128],[27.1165,35.86],[29.3743,34.4757],[31.6162,32.6162],[33.4757,30.3743],[34.86,28.1165],[35.7128,26.6838],[36.0008,24],[35.7128,21.3162],[34.86,19.8835],[33.4757,17.6257],[31.6162,15.3838],[29.3743,13.5243],[27.1165,12.14],[25.6838,11.2872],[23,10.9992],[20.3162,11.2872],[18.8835,12.14],[16.6257,13.5243],[14.3838,15.3838],[12.5243,17.6257],[11.14,19.8835],[10.2872,21.3162],[9.9992,24],[10.2872,26.6838],[11.14,28.1165],[12.5243,30.3743],[14.3838,32.6162],[16.6257,34.4757],[18.8835,35.86],[20.3162,36.7128]];
  const out=activeContour(image,w,h,snake,{alpha:.015,beta:.1,gamma:.01,wLine:0,wEdge:1,maxNumIter:250,convergence:.05,maxPxMove:1});
  let mean=0,max=0;
  for(let i=0;i<golden.length;i++){
    const d=Math.hypot(out.snake[i][0]-golden[i][0],out.snake[i][1]-golden[i][1]);
    mean+=d;max=Math.max(max,d);
  }
  mean/=golden.length;
  assert.ok(mean<.15,'mean parity error '+mean);
  assert.ok(max<.35,'max parity error '+max);
});

test('browser MorphGAC exactly matches scikit-image on analytic edge-stop fixture',()=>{
  const n=48,w=n,h=n,gimage=new Float32Array(n*n),init=new Uint8Array(n*n);
  for(let y=0;y<n;y++)for(let x=0;x<n;x++){
    const r=Math.hypot(x-24,y-23);
    gimage[y*n+x]=.08+.92*(1-Math.exp(-((r-12)**2)/(2*1.6**2)));
    init[y*n+x]=r<16?1:0;
  }
  const rle=[[0,596],[1,9],[0,37],[1,13],[0,34],[1,15],[0,32],[1,17],[0,30],[1,19],[0,28],[1,21],[0,27],[1,21],[0,26],[1,23],[0,25],[1,23],[0,25],[1,23],[0,25],[1,23],[0,25],[1,23],[0,25],[1,23],[0,25],[1,23],[0,25],[1,23],[0,25],[1,23],[0,26],[1,21],[0,27],[1,21],[0,28],[1,19],[0,30],[1,17],[0,32],[1,15],[0,34],[1,13],[0,37],[1,9],[0,643]];
  const golden=[];
  for(const [v,count] of rle)for(let i=0;i<count;i++)golden.push(v);
  const out=morphGAC(gimage,w,h,init,{numIter:50,smoothing:1,threshold:'auto',balloon:-1});
  assert.equal(out.length,golden.length);
  let diff=0;
  for(let i=0;i<out.length;i++)diff+=out[i]!==golden[i];
  assert.equal(diff,0);
});


test('browser MorphACWE matches scikit-image within raster rounding tolerance',()=>{
  const n=48,w=n,h=n,image=new Float32Array(n*n),init=new Uint8Array(n*n);
  for(let y=0;y<n;y++)for(let x=0;x<n;x++){
    const r=Math.hypot(x-24,y-23);
    image[y*n+x]=.25+.65/(1+Math.exp(-(r-12)*1.5));
    init[y*n+x]=r<16?1:0;
  }
  const rle=[[0,551],[1,3],[0,42],[1,9],[0,37],[1,13],[0,33],[1,17],[0,30],[1,19],[0,29],[1,19],[0,28],[1,21],[0,27],[1,21],[0,26],[1,23],[0,25],[1,23],[0,25],[1,23],[0,24],[1,25],[0,23],[1,25],[0,23],[1,25],[0,24],[1,23],[0,25],[1,23],[0,25],[1,23],[0,26],[1,21],[0,27],[1,21],[0,28],[1,19],[0,29],[1,19],[0,30],[1,17],[0,33],[1,13],[0,37],[1,9],[0,42],[1,3],[0,598]];
  const golden=[];for(const [v,count] of rle)for(let i=0;i<count;i++)golden.push(v);
  const out=morphACWE(image,w,h,init,{numIter:50,smoothing:1,lambda1:1,lambda2:1});
  let diff=0;for(let i=0;i<out.length;i++)diff+=out[i]!==golden[i];
  assert.ok(diff<=10,'pixel parity difference '+diff);
});
